                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objects.append((color, cells))

    # Each object's vertical position is moved to its designated edge.
    # For duplicated colors, the upper and lower instances are sent to
    # opposite edges.
    targets = {}
    by_color = {}
    for i, (color, cells) in enumerate(objects):
        by_color.setdefault(color, []).append(i)

    for color, ids in by_color.items():
        ids.sort(key=lambda i: min(y for y, x in objects[i][1]))
        if len(ids) == 2:
            targets[ids[0]] = "bottom"
            targets[ids[1]] = "top"

    out = [[0] * w for _ in range(h)]
    for i, (color, cells) in enumerate(objects):
        if i in targets:
            bottom = targets[i] == "bottom"
        else:
            top = min(y for y, x in cells)
            bottom_edge = h - 1 - max(y for y, x in cells)
            bottom = bottom_edge < top

        shift = h - 1 - max(y for y, x in cells) if bottom else -min(y for y, x in cells)
        for y, x in cells:
            out[y + shift][x] = color

    return out
